  });

  it('stops when the model finished for a reason other than tool use', () => {
    expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
  });
});

describe('accumulateUsage', () => {
  it('accumulates round usage into TotalTurnUsage across reporting rounds and keeps undefined when none report', () => {
    const round1: UsageMetadata = {inputTokens: 10, outputTokens: 2, totalTokens: 12};
    const round3: UsageMetadata = {inputTokens: 25, outputTokens: 5, totalTokens: 30};

    let total: TotalTurnUsage | undefined = accumulateUsage(undefined, undefined);
    const afterEmpty = total;
    total = accumulateUsage(total, round1);
    total = accumulateUsage(total, undefined);
    total = accumulateUsage(total, round3);

    expect({afterEmpty, total}).toEqual({
      afterEmpty: undefined,
      total: {inputTokens: 35, outputTokens: 7, totalTokens: 42},
    });
  });
});

