  it('accumulates round usage into TotalTurnUsage across reporting rounds and keeps undefined when none report', () => {
    const afterEmpty: TotalTurnUsage | undefined = accumulateUsage(undefined, undefined);
    const round1: UsageMetadata = {inputTokens: 10, outputTokens: 2, totalTokens: 12};
    const afterRound1 = accumulateUsage(afterEmpty, round1);
